import os
import requests


def stream_completion(payload, config=None):
    config = config or {}
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable is required")
    model = config.get("model", "gpt-4o-mini")
    url = "https://api.openai.com/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    messages = payload if isinstance(payload, list) else [{"role": "user", "content": str(payload)}]
    body = {
        "model": model,
        "messages": messages,
        "stream": True,
    }
    if "temperature" in config:
        body["temperature"] = config["temperature"]
    if "max_tokens" in config:
        body["max_tokens"] = config["max_tokens"]
    result = ""
    with requests.post(url, headers=headers, json=body, stream=True, timeout=config.get("timeout", 120)) as response:
        response.raise_for_status()
        for line in response.iter_lines(decode_unicode=True):
            if not line:
                continue
            if line.startswith("data: "):
                data = line[6:]
                if data == "[DONE]":
                    break
                chunk = requests.utils.json.loads(data)
                for choice in chunk.get("choices", []):
                    delta = choice.get("delta", {})
                    content = delta.get("content")
                    if content:
                        result += content
    return result
